-- Grupo Joven, «conversación» (27-11-2026): lo que se pregunta quien piensa
-- venir, contestado como en un chat (bloque nuevo «Conversación»): lo que
-- hacía el Grupo Joven en cuatro tarjetas pasa a la segunda respuesta, en
-- píldoras, y «Cómo sumarte», a la última, con el botón «Escríbenos». Después,
-- el año en fotos verticales que se deslizan (tarjetas en estilo «historias»)
-- y la cita de Timoteo sobre papel. Fuera la llamada final: el botón ya va en
-- la conversación.
--
-- Solo si la página sigue con sus bloques de partida (abre con la entradilla
-- de «se hacen amigos» y sigue con las tarjetas de «Qué hacemos»): si alguien
-- la ha rehecho en el CMS, no se toca.

UPDATE `ContenidoPagina` SET `datos` = JSON_SET(`datos`, '$.bloques', JSON_EXTRACT('[{"tipo":"texto","titulo":"","presentacion":{"estilo":"margen"},"html":"<h3>Quiénes somos</h3><p>El Grupo Joven reúne a los hermanos más jóvenes del Grupo Parroquial. Se forman juntos, echan una mano en los cultos y en la salida del Sábado de Pasión y, sobre todo, se hacen amigos alrededor de la Virgen de los <strong>Desamparados</strong>.</p>"},{"tipo":"conversacion","titulo":"Lo que nos preguntan","presentacion":{"alineacionTitulo":"centro"},"nombre":"Grupo Joven","turnos":[{"pregunta":"¿Tengo que ser hermano para ir?","respuesta":"No. Ven a conocernos y decide después. Si te quedas, el alta se hace en la web en unos minutos.","etiquetas":[],"boton":"","enlace":""},{"pregunta":"¿Y qué se hace?","respuesta":"Un poco de todo, según la época del año: encuentros para hablar de la fe sin rodeos, echar una mano antes de cada culto y salir a la calle en el Rosario de octubre y el Sábado de Pasión.","etiquetas":["Encuentros con los Pasionistas","Montar el altar","Preparar la cera","Acólitos y ciriales","Cruz de mayo","Excursiones"],"boton":"","enlace":""},{"pregunta":"¿Conoceré a gente de otros barrios?","respuesta":"Sí. En las convivencias nos juntamos con jóvenes de otros grupos de Málaga, y cada año la Agrupación de Cofradías reúne a los de toda la Semana Santa en la Misa de la Juventud Cofrade.","etiquetas":[],"boton":"","enlace":""},{"pregunta":"Vale. ¿Cómo empiezo?","respuesta":"No hace falta saber nada de antemano ni tener a nadie dentro: basta con ganas. Escríbenos y te decimos cuándo es el próximo encuentro.","etiquetas":[],"boton":"Escríbenos","enlace":"/contacto"}]},{"tipo":"tarjetas","titulo":"Así es un año","presentacion":{"fondo":"oscuro","estilo":"historias","alineacionTitulo":"izquierda"},"tarjetas":[{"titulo":"Preparar la cera","descripcion":"","enlace":"","etiqueta":"Antes de cada culto","foto":"/images/trono-candeleria.webp","fotoAlt":"El trono de la Virgen, entre la candelería"},{"titulo":"Junto a la cruz de guía","descripcion":"","enlace":"","etiqueta":"Sábado de Pasión","foto":"/images/cabeceras/cruz-de-guia-1000.webp","fotoAlt":"La cruz de guía y los banderines dentro del templo, entre nazarenos, antes de la salida"},{"titulo":"Con el cirio en la mano","descripcion":"","enlace":"","etiqueta":"Sábado de Pasión","foto":"/images/cabeceras/nazarenos-con-cirios-1000.webp","fotoAlt":"Nazarenos del Grupo Parroquial con los cirios encendidos"},{"titulo":"Las insignias en la calle","descripcion":"","enlace":"","etiqueta":"De noche","foto":"/images/cabeceras/insignias-de-noche-1000.webp","fotoAlt":"Banderines bordados en plata y cruces del cortejo, de noche por la calle"},{"titulo":"Rosario por el barrio","descripcion":"","enlace":"","etiqueta":"Octubre","foto":"/images/cabeceras/virgen-de-noche-1000.webp","fotoAlt":"La Virgen de los Desamparados de noche, en el Rosario"}]},{"tipo":"cita","titulo":"","presentacion":{"fondo":"papel","estilo":"clasica","alineacion":"centro"},"texto":"Que nadie te menosprecie por ser joven.","autor":"","fuente":"Primera carta a Timoteo, 4, 12"}]', '$'))
WHERE `slug` = 'grupo-joven'
  AND JSON_VALUE(`datos`, '$.bloques[0].html') LIKE '%se hacen amigos%'
  AND JSON_VALUE(`datos`, '$.bloques[1].tipo') = 'tarjetas';
